sys_script.script:
(function executeFlow1WithDetailedIssueMapping(current, previous) {
    if (current.u_status == 'submitted' || current.u_status == 'failed') {
        var checkMap = [
            { field: 'u_temp_check', label: 'Temperature Check' },
            { field: 'u_cleaning_check', label: 'Cleaning Check' },
            { field: 'u_hygiene_check', label: 'Hygiene Check' },
            { field: 'u_pest_check', label: 'Pest Control Check' },
            { field: 'u_expiry_check', label: 'Expiry Check' },
            { field: 'u_storage_check', label: 'Storage Check' },
            { field: 'u_equip_check', label: 'Equipment Cleanliness' }
        ];

        var failedChecks = [];
        for (var i = 0; i < checkMap.length; i++) {
            if (current.getValue(checkMap[i].field) == 'fail') {
                failedChecks.push(checkMap[i].label);
            }
        }

        if (failedChecks.length > 0) {
            current.u_status = 'failed';
            current.u_risk_level = 'critical';

            var storeName = current.u_store ? current.u_store.getDisplayValue() : 'Store 101';
            var scoreVal = current.u_overall_score || current.u_score || '71.43';
            var failedChecksText = failedChecks.join(', ');

            // Auto-create detailed Food Safety Issue record with mapped fields
            var grIss = new GlideRecord('x_fresh_guard_360_issue');
            grIss.initialize();
            grIss.setValue('u_issue_title', 'Checklist Failure: ' + failedChecksText + ' at ' + storeName);
            grIss.setValue('u_store', current.u_store);
            grIss.setValue('u_department', current.u_department);
            grIss.setValue('u_risk_level', 'high');
            grIss.setValue('u_capa_required', true);
            grIss.setValue('u_status', 'open');
            grIss.setValue('u_description', 'AUTOMATIC SAFETY ISSUE GENERATED FROM CHECKLIST\n' +
                                           '----------------------------------------\n' +
                                           'Checklist Number: ' + (current.u_checklist_number || current.u_number) + '\n' +
                                           'Store Name: ' + storeName + '\n' +
                                           'Overall Checklist Score: ' + scoreVal + '%\n' +
                                           'Failed Inspection Checks: ' + failedChecksText + '\n' +
                                           'Department: ' + current.u_department);
            var issueSysId = grIss.insert();
            gs.info('[FLOW 1] Auto-Created Detailed Food Safety Issue: ' + issueSysId);
        } else {
            current.u_status = 'completed';
        }
    }
})(current, previous);
